class TestBug002(unittest.TestCase):
    """BUG-002: cloud-archive must detect concurrent current VersionId (REQ-004)."""

    @unittest.expectedFailure
    def test_bug_002_cloud_archive_detects_concurrent_version(self) -> None:
        """[BUG-002][Req: REQ-004] compare live current VersionId before hide.

        Desired: Head/compare scheduled provider_version_id before unversioned
        delete_object. Current: delete_object(Bucket, Key) only at 2099-2102.
        Fix patch: quality/workspace/patches/BUG-002-fix.patch
        """
        body = _cloud_archive_body()
        self.assertIn("delete_object(", body)
        # Desired correct behavior: inspect current generation before marker.
        self.assertTrue(
            ("head_object(" in body) or ("HeadObject" in body),
            "cloud-archive must Head current object before creating delete marker",
        )
        self.assertIn("provider_version_id", body)
        # Scheduled version must be compared to live VersionId (not only loaded).
        self.assertRegex(
            body,
            r"VersionId|provider_version_id.*=|!=.*provider_version_id|provider_version_id.*!=",
        )
        # The delete_object call site must not be the only use of the scheduled id.
        delete_idx = body.index("delete_object(")
        before_delete = body[:delete_idx]
        self.assertTrue(
            "head_object(" in before_delete.lower()
            or "head_object(" in before_delete
            or "HeadObject" in before_delete,
            "Head/compare must occur before delete_object",
        )




class TestBug004(unittest.TestCase):
    """BUG-004: csrf_token_for must honor session_version (REQ-008)."""

    def setUp(self) -> None:
        self._directory = tempfile.TemporaryDirectory()
        self.addCleanup(self._directory.cleanup)
        self.database_path = Path(self._directory.name) / "csrf.db"
        migrated = run_alembic(self.database_path)
        self.assertEqual(migrated.returncode, 0, migrated.stderr)

    @unittest.expectedFailure
    def test_bug_004_csrf_honors_session_version(self) -> None:
        """[BUG-004][Req: REQ-008] force-logout must invalidate CSRF lookup.

        Desired: after users.session_version bump, csrf_token_for returns None
        just like resolve_session. Current: token still returned (sessions.py:115-137).
        Fix patch: quality/workspace/patches/BUG-004-fix.patch
        """
        # Source shape: csrf body must mention session_version (desired).
        self.assertIn(
            "session_version",
            _csrf_body(),
            "csrf_token_for must consult session_version",
        )
        with SQLiteConnection(str(self.database_path)) as connection:
            user = connection.execute(
                """
                INSERT INTO users(username, display_name, password_hash, is_admin, active)
                VALUES ('csrf-user', 'CSRF', 'hash', TRUE, TRUE)
                RETURNING id
                """
            ).fetchone()
            token = create_session(
                connection, user_id=user["id"], auth_method="local"
            )
            self.assertIsNotNone(csrf_token_for(connection, token))
            self.assertIsNotNone(resolve_session(connection, token))
            connection.execute(
                "UPDATE users SET session_version=session_version+1 WHERE id=%s",
                (user["id"],),
            )
            self.assertIsNone(resolve_session(connection, token))
            # Desired correct behavior:
            self.assertIsNone(
                csrf_token_for(connection, token),
                "csrf_token_for must return None after session_version bump",
            )


